import urllib.request, urllib.error, json

def req(method, url, body=None, ctype="application/json"):
    data=None
    headers={"Accept":"application/json"}
    if body is not None:
        if isinstance(body, (dict,list)):
            data=json.dumps(body).encode()
        elif isinstance(body, str):
            data=body.encode()
        else:
            data=body
        headers["Content-Type"]=ctype
    r=urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(r, timeout=20) as resp:
            b=resp.read()
            print(f"{method} {url} -> {resp.status} Link={resp.headers.get('Link')} body={b[:800]!r}")
            return resp.status, resp.headers.get("Link"), b
    except urllib.error.HTTPError as e:
        b=e.read()
        print(f"{method} {url} -> HTTP {e.code} body={b[:800]!r}")
        return e.code, None, b
    except Exception as e:
        print(f"{method} {url} -> ERR {type(e).__name__}: {e}")
        return None, None, b""

